tasks.solution:
#include <stdio.h>

struct Box {
    int count;
    int price;
};

// 남은 수량이 n 이상일 때만 n개를 꺼내려는 함수예요.
void take(struct Box *b, int n) {
    if (b->count >= n) {
        b->count = b->count - n;
    }
}

int main(void) {
    struct Box box = {5, 500};
    take(&box, 3);
    take(&box, 4);
    printf("%d", box.count);
    return 0;
}

