#include <stdio.h>

struct Item {
    int code;
    int qty;
    int (*rule)(int);
};

int twice(int v) {
    return v * 2;
}
int minus3(int v) {
    return v - 3;
}

// pp를 한 번 따라가 진열대에서 from번 상자를 to번 자리에 그대로 옮겨 놓으려 해요.
void copy_item(struct Item **pp, int to, int from) {
    (*pp)[to].qty = (*pp)[from].qty;
}

int main(void) {
    struct Item shelf[3] = {{11, 4, twice}, {25, 7, twice}, {37, 5, minus3}};
    struct Item *p = shelf;
    copy_item(&p, 0, 2);
    p++;
    // 이 상자의 수량에 바로 앞 상자의 규칙을 적용해요.
    p->qty = (p - 1)->rule(p->qty);
    printf("%d %d %d", shelf[0].code, shelf[0].qty, shelf[1].qty);
    return 0;
}

